parameters.jsCode:
// One row per visitor per day: everything recorded, nothing judged.
// The verdict is the next node's business, so a new engine reads the same row.
const visits = $input.all().map((i) => i.json).filter((r) => r && r.ip && Number.isFinite(Date.parse(r.ts)));

// A verdict outlives the visit rows, so it carries no address: a short hash to
// tell visitors apart, and the network the address sits in.
const hash = (s) => { let h = 0x811c9dc5; for (const c of String(s)) { h ^= c.charCodeAt(0); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
const net = (ip) => (ip.includes(':') ? ip.split(':').slice(0, 3).join(':') + '::' : ip.split('.').slice(0, 3).join('.') + '.x');
// Your own networks, as address prefixes. Set in the n8n UI, never in the public copy.
// Their rows are counted as yours, not judged: otherwise you are the day's likeliest human.
const SELF_NETS = ['YOUR_HOME_NET_PREFIX.'];

// Yesterday only: a whole day, judged once.
const yesterday = new Date(Date.now() - 86400e3).toISOString().slice(0, 10);
const groups = new Map();
for (const v of visits) {
  const day = new Date(Date.parse(v.ts)).toISOString().slice(0, 10);
  const key = day + '|' + hash(v.ip);
  if (day !== yesterday) continue;
  if (!groups.has(key)) groups.set(key, { day, ip: v.ip, rows: [] });
  groups.get(key).rows.push(v);
}

const out = [];
for (const [key, g] of groups) {
  const rows = g.rows.sort((a, b) => Date.parse(a.ts) - Date.parse(b.ts));
  const views = rows.filter((r) => r.event === 'pageview');
  const clicks = rows.filter((r) => r.event !== 'pageview');
  const times = views.map((r) => Date.parse(r.ts));
  const gaps = times.slice(1).map((t, i) => (t - times[i]) / 1000);
  out.push({ json: {
    id: key,
    day: g.day,
    visitor: hash(g.ip),
    net: net(g.ip),
    country: rows[0].country || '',
    city: rows[0].city || '',
    ua: String(rows[0].ua || '').slice(0, 300),
    flag: (rows.find((r) => r.flag) || {}).flag || '',
    agents: new Set(rows.map((r) => String(r.ua || ''))).size,
    events: rows.length,
    views: views.length,
    clicks: clicks.length,
    paths: new Set(views.map((r) => r.path)).size,
    first_path: rows[0].path || '',
    pages: [...new Set(views.map((r) => r.path))].join(' → ').slice(0, 300),
    referrer: String(rows[0].referrer || '').slice(0, 200),
    span_s: Math.round((Date.parse(rows.at(-1).ts) - Date.parse(rows[0].ts)) / 1000),
    fastest_gap_s: gaps.length ? Math.round(Math.min(...gaps) * 10) / 10 : '',
    sign_in: clicks.some((r) => /sign.?in|log.?in/i.test(String(r.target || '') + ' ' + String(r.path || ''))),
    self: SELF_NETS.some((n) => g.ip.startsWith(n)),
  } });
}
return out;

// The engine: reads one visitor's row, writes predicted, score and reason.
// Swap this node to try another engine; write its answer to a column of its
// own and the two can be compared against 'actual'.
//
// score is how bot-like, 0 to 1. Each rule that fires moves it and names itself.
const RULES = [
  // flag is the site's own word, set where the visit was recorded.
  { why: 'names itself a bot', move: +0.7, when: (v) => v.flag === 'bot-ua' },
  { why: 'browser years out of date', move: +0.5, when: (v) => v.flag === 'stale-browser' },
  { why: 'no browser named', move: +0.5, when: (v) => !/mozilla\//i.test(v.ua) },
  { why: 'pages under a second apart', move: +0.4, when: (v) => v.fastest_gap_s !== '' && v.fastest_gap_s < 1 },
  { why: 'more pages than a person reads', move: +0.3, when: (v) => v.paths >= 15 },
  { why: 'several browsers from one address', move: +0.2, when: (v) => v.agents > 1 },
  { why: 'one view and gone', move: +0.15, when: (v) => v.events === 1 },
  { why: 'clicked', move: -0.25, when: (v) => v.clicks > 0 },
  { why: 'pressed sign-in', move: -0.3, when: (v) => v.sign_in },
  { why: 'read several pages at a human pace', move: -0.15, when: (v) => v.paths >= 2 && v.fastest_gap_s !== '' && v.fastest_gap_s >= 3 },
];
const START = 0.3;
const BOT_FROM = 0.7;
const HUMAN_TO = 0.3;

return $input.all().map((item) => {
  // 'self' is not a column: your own rows keep the verdict 'self' instead of one judged.
  const { self, ...v } = item.json;
  if (self) return { json: { ...v, predicted: 'self', score: '', reason: 'your own network' } };
  const fired = RULES.filter((r) => r.when(v));
  const score = Math.min(1, Math.max(0, fired.reduce((s, r) => s + r.move, START)));
  return { json: {
    ...v,
    predicted: score >= BOT_FROM ? 'bot' : score <= HUMAN_TO ? 'human' : 'unsure',
    score: Math.round(score * 100) / 100,
    reason: fired.map((r) => r.why).join('; '),
  } };
});

