// Briefing plugin: the SITE section. Yesterday's visitors, one count, judged.
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
//
// PLAIN TEXT ONLY, never HTML. The briefing escapes centrally.
// A visitor is one address on one UTC day: a verdict row. Every count below is
// of visitors, never of views, so the lines add up to the head line.
const MAX_LINES = 5;
const input = $('When Called for Briefing').first().json;
const day = new Date(Date.parse(input.date || new Date().toISOString()) - 86400e3).toISOString().slice(0, 10);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id && r.day === day);

const of = (p) => rows.filter((r) => r.predicted === p);
const n = (k, word) => k + ' ' + word + (k === 1 ? '' : 's');
const tally = (list, keyOf) => {
  const t = {};
  for (const r of list) for (const k of keyOf(r)) if (k) t[k] = (t[k] || 0) + 1;
  return Object.entries(t).sort((a, b) => b[1] - a[1]);
};
// Where a visitor came from, off the referrer of their first event.
const sourceOf = (referrer) => {
  const ref = String(referrer ?? '');
  if (!ref) return 'direct';
  if (/promptpotter\./i.test(ref)) return '';
  if (/google|bing\.|duckduckgo|yandex|ecosia|brave\./i.test(ref)) return 'search';
  if (/linkedin/i.test(ref)) return 'LinkedIn';
  if (/github/i.test(ref)) return 'GitHub';
  const host = /^[a-z-]+:\/\/([^/]+)/i.exec(ref);
  return host ? host[1].replace(/^www\./, '') : 'other';
};

// Visitors from one place for one reason are one line: "×4" is four addresses.
// What ties them is said when it is known, so four lines that look alike read
// as one network, one browser, or four strangers.
const place = (r) => [r.city, r.country].filter(Boolean).join(', ') || r.net;
// The device, off the user agent; the same rule wherever a message says where a visitor is.
const deviceOf = (ua) => {
  const s = String(ua ?? '').trim();
  return !s ? '' : /iPad|Tablet/.test(s) ? 'tablet' : /Mobi|Android|iPhone/.test(s) ? 'phone' : 'computer';
};
// Several addresses: one word when every one agrees, a count of each known device when not.
const devicesText = (list) => {
  const t = {};
  for (const d of list) if (d) t[d] = (t[d] || 0) + 1;
  const e = Object.entries(t).sort((a, b) => b[1] - a[1]);
  return e.length === 1 && e[0][1] === list.length ? e[0][0] : e.map(([d, k]) => k + ' ' + d + (k === 1 ? '' : 's')).join(', ');
};
const groupLine = (g) => {
  const views = g.map((r) => Number(r.views) || 0);
  const same = (k) => g.every((r) => r[k] === g[0][k]);
  const ties = g.length > 1 ? [same('net') && 'same network', same('ua') && 'same browser'].filter(Boolean).join(', ') : '';
  const viewText = g.length === 1 ? n(views[0], 'view')
    : views.every((v) => v === views[0]) ? n(views[0], 'view') + ' each'
    : n(views.reduce((s, v) => s + v, 0), 'view') + ' in all';
  return [place(g[0]) + (g.length > 1 ? ' ×' + g.length : ''), devicesText(g.map((r) => deviceOf(r.ua))), ties, viewText, same('pages') ? g[0].pages : '', g[0].reason || 'no rule fired']
    .filter(Boolean).join(' · ');
};
const groupsOf = (list) => {
  const groups = new Map();
  for (const r of list.sort((a, b) => Number(b.score) - Number(a.score))) {
    const k = place(r) + '|' + r.reason;
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(r);
  }
  return [...groups.values()];
};

const judged = rows.filter((r) => r.actual === 'bot' || r.actual === 'human');
const right = judged.filter((r) => r.actual === r.predicted).length;
const yours = of('self').reduce((s, r) => s + (Number(r.events) || 0), 0);
const visitors = rows.filter((r) => r.predicted !== 'self');
// People and unsure visitors are the audience; bots are counted, never tallied.
const audience = visitors.filter((r) => r.predicted !== 'bot');

const blocks = [];
if (visitors.length) {
  const people = of('human').length;
  const head = [n(visitors.length, 'visitor') + ': ' + people + (people === 1 ? ' person · ' : ' people · ') + of('unsure').length + ' unsure · ' + n(of('bot').length, 'bot')];
  const pressed = audience.filter((r) => String(r.sign_in) === 'true').length;
  head.push('sign-in pressed ' + pressed);
  blocks.push({ items: head });
  for (const [heading, p] of [['People', 'human'], ['Unsure', 'unsure'], ['Bots', 'bot']]) {
    const groups = groupsOf(of(p));
    const items = groups.slice(0, MAX_LINES).map(groupLine);
    const rest = groups.slice(MAX_LINES).reduce((s, g) => s + g.length, 0);
    if (rest) items.push('+' + n(rest, 'more visitor'));
    if (items.length) blocks.push({ heading, items });
  }
  const pages = tally(audience, (r) => String(r.pages || '').split(' → ')).slice(0, 5);
  if (pages.length) blocks.push({ heading: 'Pages (visitors per page, no bots)', items: [pages.map(([p, k]) => p + ' ' + k).join(' · ')] });
  const from = tally(audience, (r) => [r.country]).slice(0, 6);
  if (from.length) blocks.push({ heading: 'From (visitors per country, no bots)', items: [from.map(([c, k]) => c + ' ' + k).join(' · ')] });
  const via = tally(audience, (r) => [sourceOf(r.referrer)]);
  if (via.length) blocks.push({ heading: 'Via (visitors per source, no bots)', items: [via.map(([s, k]) => s + ' ' + k).join(' · ')] });
  const devices = tally(audience, (r) => [deviceOf(r.ua)]);
  if (devices.length) blocks.push({ heading: 'Devices (visitors per device, no bots)', items: [devices.map(([d, k]) => d + ' ' + k).join(' · ')] });
}
if (yours) blocks.push({ items: [(visitors.length ? '' : 'No outside visitors ') + '(you: ' + n(yours, 'event') + ', not counted)'] });
if (judged.length) blocks.push({ heading: 'Checked by hand', items: [right + ' of ' + judged.length + ' predicted right'] });

// The headline for the section header / its cluster line.
const people = of('human').length;
const summary = visitors.length
  ? n(visitors.length, 'site visitor') + ' (' + people + (people === 1 ? ' person)' : ' people)')
  : 'no site visitors';

// Always exactly one item: zero items is indistinguishable from a crash.
return [{ json: { key: 'site', icon: '👀', title: 'SITE · yesterday', summary, blocks, empty: 'No visitors' } }];
